import{_ as a,o as t,c as o,a3 as d}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Tenant API v1 — Calendar","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Calendar | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-calendar"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Calendar | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-calendar"}]]},"headers":[],"relativePath":"api/tenant-v1-calendar.md","filePath":"api/tenant-v1-calendar.md","lastUpdated":1791326286000}'),c={name:"api/tenant-v1-calendar.md"};function n(r,e,s,i,l,h){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="tenant-api-v1-—-calendar" tabindex="-1">Tenant API v1 — Calendar <a class="header-anchor" href="#tenant-api-v1-—-calendar" aria-label="Permalink to &quot;Tenant API v1 — Calendar&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:calendar</code>, plus <code>can:calendar.*</code> / policies.</p><p>Visibility: without <code>calendar.view_all</code>, events where <code>organizer_id</code> is the current user, <strong>or</strong> meeting projections where the actor is on <code>meeting_attendees.user_id</code>, <strong>or</strong> manual events shared via <code>calendar_event_shares</code>. Invitees and <strong>viewer</strong> shares receive <code>read_only: true</code> and cannot update/cancel/delete. <strong>Editor</strong> shares may mutate manual events when they also have Spatie <code>calendar.update</code> / <code>delete</code>. No calendar assignment — <code>organizer_id</code> and <code>assignee_id</code> are prohibited on write payloads.</p><h2 id="upcoming" tabindex="-1">Upcoming <a class="header-anchor" href="#upcoming" aria-label="Permalink to &quot;Upcoming&quot;">​</a></h2><h3 id="get-calendar-upcoming" tabindex="-1">GET <code>/calendar/upcoming</code> <a class="header-anchor" href="#get-calendar-upcoming" aria-label="Permalink to &quot;GET `/calendar/upcoming`&quot;">​</a></h3><p>Query: <code>limit</code> (1–25, default 8). Scheduled events with <code>starts_at &gt;= now()</code>, visibility-scoped.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><h3 id="get-calendar-events" tabindex="-1">GET <code>/calendar/events</code> <a class="header-anchor" href="#get-calendar-events" aria-label="Permalink to &quot;GET `/calendar/events`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code>, <code>from</code>, <code>to</code>, <code>trashed</code>, <code>sort</code> (default <code>starts_at</code>), <code>direction</code> (default <code>asc</code>), <code>page</code>, <code>per_page</code>, <code>paginate</code> (<code>0</code>/<code>false</code> returns a non-paginated range collection when <code>from</code>+<code>to</code> are set).</p><p>Events may have <code>source</code> <code>manual</code> | <code>meeting</code> | <code>project</code> | <code>task</code> | <code>lead</code> (sourced overlays are read on the grid; mutate via the parent module). Responses include <code>read_only</code> (boolean) for SPA gating, and nullable <code>external_provider</code> (<code>google</code>|<code>microsoft</code>) / <code>external_event_id</code> when the event has been pushed to a connected Calendar sync provider (<strong>1.4.0</strong>).</p><h3 id="post-calendar-events" tabindex="-1">POST <code>/calendar/events</code> <a class="header-anchor" href="#post-calendar-events" aria-label="Permalink to &quot;POST `/calendar/events`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>description</code>, <code>starts_at</code>, <code>ends_at</code> (<code>after_or_equal:starts_at</code>), <code>all_day</code>, <code>timezone</code>, <code>color</code>.</p><p>Sets <code>organizer_id</code> to the authenticated user. Status <code>scheduled</code>, source <code>manual</code>.</p><h3 id="get-calendar-events-id" tabindex="-1">GET <code>/calendar/events/{id}</code> <a class="header-anchor" href="#get-calendar-events-id" aria-label="Permalink to &quot;GET `/calendar/events/{id}`&quot;">​</a></h3><h3 id="put-calendar-events-id" tabindex="-1">PUT <code>/calendar/events/{id}</code> <a class="header-anchor" href="#put-calendar-events-id" aria-label="Permalink to &quot;PUT `/calendar/events/{id}`&quot;">​</a></h3><p>Same writable fields as create (partial). Organizer/source/status fields prohibited.</p><p>Used by the SPA form and by Week/Day <strong>drag-and-drop</strong> reschedule (<code>starts_at</code> + <code>ends_at</code> only).</p><h3 id="post-calendar-events-id-cancel" tabindex="-1">POST <code>/calendar/events/{id}/cancel</code> <a class="header-anchor" href="#post-calendar-events-id-cancel" aria-label="Permalink to &quot;POST `/calendar/events/{id}/cancel`&quot;">​</a></h3><p>Sets <code>status=cancelled</code> and <code>cancelled_at</code>.</p><h3 id="delete-calendar-events-id" tabindex="-1">DELETE <code>/calendar/events/{id}</code> <a class="header-anchor" href="#delete-calendar-events-id" aria-label="Permalink to &quot;DELETE `/calendar/events/{id}`&quot;">​</a></h3><p>Soft delete.</p><h2 id="shares-manual-events" tabindex="-1">Shares (manual events) <a class="header-anchor" href="#shares-manual-events" aria-label="Permalink to &quot;Shares (manual events)&quot;">​</a></h2><p>Organizer or <code>calendar.view_all</code> may manage shares.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/calendar/events/{id}/shares</code></td><td>List shares</td></tr><tr><td>POST</td><td><code>/calendar/events/{id}/shares</code></td><td>Body: <code>user_id</code>, <code>access</code> (<code>viewer</code>|<code>editor</code>)</td></tr><tr><td>PUT</td><td><code>/calendar/events/{id}/shares/{share}</code></td><td>Body: <code>access</code></td></tr><tr><td>DELETE</td><td><code>/calendar/events/{id}/shares/{share}</code></td><td>Remove share</td></tr></tbody></table><h2 id="integrations-google-outlook-sync-—-1-4-0" tabindex="-1">Integrations (Google / Outlook sync — 1.4.0) <a class="header-anchor" href="#integrations-google-outlook-sync-—-1-4-0" aria-label="Permalink to &quot;Integrations (Google / Outlook sync — 1.4.0)&quot;">​</a></h2><p>Requires <code>calendar.manage_integrations</code>. Per-user connections; one-way push for manual events only (see <a href="/developer-guide/calendar#google-outlook-sync-1-4-0">developer guide</a>).</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/calendar/integrations</code></td><td>Status per provider (<code>google</code>, <code>microsoft</code>) for the authenticated user: <code>connected</code> (bool), <code>status</code>, <code>external_calendar_id</code>, <code>connected_at</code></td></tr><tr><td>GET</td><td><code>/calendar/integrations/{provider}/authorize</code></td><td>Returns the OAuth authorize URL to redirect the browser to; 422 if the platform has no client id/secret configured for that provider</td></tr><tr><td>DELETE</td><td><code>/calendar/integrations/{provider}</code></td><td>Disconnects; stops future pushes, does not remove events already created on the provider</td></tr></tbody></table><p>OAuth callback (platform, not under <code>/api/tenant/v1</code>): <code>GET /api/oauth/calendar-sync/{provider}/callback</code> → redirects the browser to <code>{FRONTEND_URL}/#/calendar?integrations={status}</code>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>calendar.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>view_all</code> · <code>manage_integrations</code></p>',31)])])}const m=a(c,[["render",n]]);export{u as __pageData,m as default};
